const events: any[] = [];
function dec(...args: any[]): any { events.push(['decorate', args.length, args[1] === undefined ? 'class' : String(args[1])]); }
function replace(value: any): any { events.push(['replace', value.name]); return class extends value { static replacement = true; }; }
class Base { value: number = 1; get amount(): number { return this.value; } set amount(n: number) { this.value = n; } }
export class C extends Base { @dec get #amount(): number { return super.amount; } @dec set #amount(n: number) { super.amount = n; } run(): number { this.#amount = 2; return this.#amount; } }
export const result: any = [new C().run(), events];

